<?php require __DIR__.'/partials/header.php'; $rows=[]; try{$rows=q("SELECT s.*,p.close,p.ts FROM stocks s LEFT JOIN prices p ON p.symbol=s.symbol AND p.ts=(SELECT MAX(ts) FROM prices x WHERE x.symbol=s.symbol) ORDER BY s.market_cap DESC LIMIT 12")->fetchAll();}catch(Throwable $x){} ?><section class="hero"><div><span class="eyebrow">QUANTITATIVE MARKET TERMINAL</span><h1>Research markets without the clutter.</h1><p>Fast local analytics, cached history, fundamentals and technical studies.</p></div><a class="primary" href="screener.php">Open screener</a></section><div class="grid three"><article class="card"><small>Universe</small><strong><?=count($rows)?count($rows):'—'?></strong><span>Cached symbols</span></article><article class="card"><small>Data status</small><strong><?=count($rows)?'Ready':'Waiting'?></strong><span>Latest PHP cache</span></article><article class="card"><small>Mode</small><strong>Research</strong><span>Historical analytics</span></article></div><section class="section-head"><div><span class="eyebrow">MARKET BOARD</span><h2>Tracked universe</h2></div></section><div class="table-card"><table><thead><tr><th>Symbol</th><th>Price</th><th>Market cap</th><th>P/E</th><th>Updated</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="stock.php?symbol=<?=e($r['symbol'])?>"><b><?=e($r['symbol'])?></b></a></td><td><?=e($r['close']??'—')?></td><td><?=e($r['market_cap']??'—')?></td><td><?=e($r['pe']??'—')?></td><td><?=e($r['ts']??'—')?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5">No imported market data yet. Run the collector and import its cache.</td></tr><?php endif;?></tbody></table></div><?php require __DIR__.'/partials/footer.php'; ?>